$ErrorActionPreference='Stop'
$repo='C:\Users\Xxkan\mhw-mods-work-canonical'
$wt='C:\Users\Xxkan\AppData\Local\Temp\mhw-pr128-validate'
Set-Location $repo
& git fetch origin main integration/bridge-priority-aging-main-20260929
if($LASTEXITCODE -ne 0){ throw 'fetch failed' }
if(Test-Path $wt){ & git worktree remove --force $wt 2>$null; if(Test-Path $wt){Remove-Item -LiteralPath $wt -Recurse -Force} }
& git worktree add --detach $wt origin/integration/bridge-priority-aging-main-20260929
if($LASTEXITCODE -ne 0){ throw 'worktree add failed' }
Push-Location $wt
try {
  & python -m py_compile heaven-bridge/worker.py
  if($LASTEXITCODE -ne 0){ throw 'py_compile failed' }
  & python heaven-bridge/test_worker.py
  if($LASTEXITCODE -ne 0){ throw 'test_worker.py failed' }
  & python heaven-bridge/tests/test_worker.py
  if($LASTEXITCODE -ne 0){ throw 'tests/test_worker.py failed' }
  & git diff --check origin/main...HEAD
  if($LASTEXITCODE -ne 0){ throw 'diff check failed' }
  Write-Output ('VALIDATED_SHA='+(& git rev-parse HEAD).Trim())
} finally {
  Pop-Location
  Set-Location $repo
  & git worktree remove --force $wt | Out-Null
}
